[tool error]
{
  "ok": false,
  "name": "place_text",
  "error": {
    "type": "invalid_params",
    "message": "'space' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "position": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "[x, y]"
        },
        "content": {
          "type": "string",
          "minLength": 1
        },
        "height": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "text height in space units (feet in model, inches on sheets)"
        },
        "style": {
          "type": "string",
          "minLength": 1
        },
        "rotation_deg": {
          "type": "number"
        },
        "halign": {
          "type": "string",
          "enum": [
            "left",
            "center",
            "right"
          ]
        },
        "valign": {
          "type": "string",
          "enum": [
            "bottom",
            "middle",
            "top"
          ]
        }
      },
      "required": [
        "space",
        "position",
        "content",
        "height"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "SH-004",
      "position": [
        17.0,
        20.5
      ],
      "content": "ROADWAY PLAN",
      "height": 0.25,
      "halign": "center"
    }
  },
  "warnings": []
}
